ANNOTATIONS = [
    (85, 'after', r'''initializeAgentMcpServers：agent 可以在自己的 frontmatter 里定义 MCP 服务器，与父级 clients 加性合并——agent 启动时连上，agent 结束时清理。'''),
    (109, 'after', r'''快速路径：没定义自己的服务器就直接返回父级 clients，tools 空数组、cleanup 空函数，零开销。'''),
    (117, 'after', r'''plugin-only 锁只拦 user-controlled agent：plugin / built-in / policySettings 属于 admin-trusted，它们 frontmatter 里的 MCP 是管理员批准面的一部分。第一版全拦把合规插件 agent 拦死了，违背「plugin-provided always loads」的设计，才按 source 细分。'''),
    (133, 'after', r'''主循环前先建两个账本：newlyCreatedClients 只记内联定义新建的连接（结束时才清），agentTools 收集这个 agent 专属的工具。'''),
    (140, 'before', r'''spec 两种形态分支：string 按名字引用已有配置，对象是内联定义。'''),
    (155, 'after', r'''内联定义必须恰好一个键（{ [name]: config }），多键说明用户写错了，警告后跳过。'''),
    (173, 'after', r'''真正发起连接。内联定义的 config 会盖上 scope: 'dynamic'，与配置文件里的静态服务器区分。'''),
    (191, 'after', r'''连上才 fetchToolsForClient 拉工具列表；连接失败（client.type 不是 connected）只记警告不抛错——一个坏服务器不该让整个 agent 起不来。'''),
    (210, 'after', r'''cleanup 只清 newlyCreatedClients：按名字引用的是 memoize 过的共享 client，父级上下文还在用，清了会把父级的连接也拆掉。'''),
    (217, 'after', r'''返回三件套：合并后的 clients（父在前、agent 在后）、agent 自己的 tools、cleanup。'''),
    (225, 'after', r'''QueryMessage 联合类型：query() 实际可能 yield 的五族消息——流事件、请求开始、普通消息、工具结果摘要、墓碑消息。'''),
    (227, 'after', r'''isRecordableMessage：只有 assistant / user / progress / compact_boundary 四种值得落盘，stream_event 这类 delta 不录（量大且可重放）。'''),
    (248, 'before', r'''runAgent 主函数：async generator，把 query() 的消息逐个 yield 给调用方（AgentTool.tsx）。参数面就是 subagent 的全部可调维度：模型、轮数、工具池、fork 上下文、隔离模式等。'''),
    (333, 'after', r'''permissionMode 从 AppState 取，后面 agentGetAppState 会在此基础上做覆盖。'''),
    (338, 'after', r'''rootSetAppState 永远指向根 AppState store：父级本身是 async agent 时（嵌套 async→async），toolUseContext.setAppState 是 no-op，hooks / bash tasks 这类 session 级写入必须走这条备用通道，否则静默丢失。'''),
    (345, 'after', r'''getAgentModel 四级解析：agentDefinition.model → 主循环模型 → 显式 model 参数 → permissionMode 推断。'''),
    (347, 'after', r'''agentId 可被 override 指定（resume 场景要复用原 id），否则随机生成。'''),
    (353, 'after', r'''transcriptSubdir 把 agent 的 transcript 归到子目录（如 workflows/<runId>/），resume 时按 id 能找到。'''),
    (359, 'after', r'''Perfetto 追踪注册：parentId 取 toolUseContext.agentId，没有则退化为 sessionId——调用层级图里 subagent 挂在正确父节点下。'''),
    (366, 'after', r'''ant 构建才打印 subagent 的 API dump 路径（内部调试用）。'''),
    (373, 'after', r'''fork 场景的上下文消息先过 filterIncompleteToolCalls：去掉没有结果的孤儿 tool_use，否则 API 直接 400。'''),
    (378, 'after', r'''readFileState 二分叉：fork 时克隆父级缓存（保留「已读过」的记忆，避免重复读同一文件），否则新建带大小限制的缓存。'''),
    (383, 'after', r'''userContext / systemContext 可被 override 整体替换，默认取全局上下文。'''),
    (398, 'after', r'''shouldOmitClaudeMd：Explore/Plan 这类只读 agent 不需要 commit/PR/lint 规则——主 agent 有完整 CLAUDE.md 并解读它们的输出。全舰队 34M+ 次 Explore spawn，省 ~5-15 Gtok/周。显式 override.userContext 优先；kill-switch tengu_slim_subagent_claudemd 默认 true，翻 false 可回退。'''),
    (410, 'after', r'''Explore/Plan 还剔掉 parent-session-start 的 gitStatus（最多 40KB 且明确标注 stale）：需要 git 信息它们自己跑 git status 拿新鲜数据。再省 ~1-3 Gtok/周。'''),
    (434, 'after', r'''permissionMode 覆盖优先级：agent 自己定义的 mode 压不过父级的 bypassPermissions / acceptEdits / auto（auto 还要 TRANSCRIPT_CLASSIFIER 开着才压）——用户显式选择和更宽松的父级模式永远优先，agent 定义不能偷偷放宽。'''),
    (451, 'after', r'''shouldAvoidPermissionPrompts：不能弹 UI 的 agent 自动拒权限对话框。bubble 模式恒 false（冒泡到父终端）；默认同步 agent 能弹、异步不能；canShowPermissionPrompts 可显式指定（进程内队友是「异步但共享终端」的特例）。'''),
    (463, 'after', r'''awaitAutomatedChecksBeforeDialog：后台 agent 弹对话框前先等自动化检查（分类器、权限钩子）——后台运行等得起，用户只该在自动检查解决不了时才被打断。'''),
    (479, 'after', r'''allowedTools 整体替换 session 级规则（父级审批不透传给 agent），但 cliArg 规则必须保留——那是 SDK --allowedTools 消费方的显式授权，对所有 agent 生效。'''),
    (497, 'after', r'''effort 覆盖 + 引用相等短路：toolPermissionContext 和 effortValue 都没变就返回原 state 对象，避免下游无意义重渲染。'''),
    (502, 'after', r'''useExactTools 直接透传工具池（fork 路径要字节级一致的 API 前缀吃 prompt cache），否则过 resolveAgentTools 按 agentDefinition 的 tools/disallowedTools 过滤。'''),
    (506, 'after', r'''additionalWorkingDirectories 从 AppState 取键集合，喂给系统提示的环境详情段。'''),
    (518, 'after', r'''系统提示：override 优先，否则 getAgentSystemPrompt——agentDefinition.getSystemPrompt() 抛异常时回落 DEFAULT_AGENT_PROMPT，agent 定义坏掉不该让 agent 起不来。'''),
    (528, 'after', r'''abortController 三级：override > 异步 agent 新控制器（独立运行，父级 Ctrl+C 杀不掉它）> 同步 agent 共享父级（父级中断它也跟着死）。'''),
    (543, 'after', r'''SubagentStart 钩子：for-await 逐个 yield，只收 additionalContexts 字段。'''),
    (555, 'after', r'''hook context 包成 attachment user message 注入初始消息（与 SessionStart/UserPromptSubmit 的处理一致），toolUseID 用随机 UUID。'''),
    (575, 'after', r'''frontmatter 钩子注册：isAgent=true 把 Stop 钩子转成 SubagentStop（subagent 触发的是 SubagentStop）。plugin-only 门在这里按 source 判——在执行时 blanket-block 会把插件 agent 的钩子一起杀掉，所以在注册这个知道 source 的点位拦。'''),
    (646, 'after', r'''skills 预加载：三种解析策略（精确匹配 / 插件名前缀 / 任意以 :skillName 结尾）定位命令，再并发取 prompt 内容；带 formatSkillLoadingMetadata 让 UI 显示「正在加载技能」。找不到的技能只警告不阻断。'''),
    (664, 'after', r'''agent MCP 工具与 resolvedTools 按 name 合并去重；没有 agent MCP 工具时跳过 spread + uniqBy 开销（resolvedTools 内部已去过重）。'''),
    (695, 'after', r'''agentOptions 三个关键差异：isNonInteractiveSession 异步恒 true；thinkingConfig 常规 subagent 禁用以省输出 token，fork 子继承父级配置保 cache 命中；querySource 只在 fork 路径挂 options——递归 fork 守卫要读它，且要能扛过 autocompact（只重写消息不重写 options，消息扫描兜底会被 autocompact 换掉 fork 样板消息而失效）。'''),
    (714, 'after', r'''createSubagentContext：同步 agent 与父级共享 setAppState/setResponseLength/abortController，异步 agent 全隔离（除了显式传的非链接控制器）。'''),
    (719, 'after', r'''preserveToolUseResults：进程内队友的 transcript 可查看，保留 toolUseResult 字段。'''),
    (730, 'after', r'''onCacheSafeParams 回调：后台摘要用它在系统提示/上下文/工具构造完成后 fork agent 对话，共享 prompt cache。'''),
    (742, 'after', r'''初始消息和 agentType 元数据落盘都是 fire-and-forget：持久化失败只记日志，不阻塞 agent 启动。'''),
    (745, 'after', r'''lastRecordedUuid 跟踪最后一条已录消息的 UUID：每条新消息 O(1) 挂到父链后面，不用整表重写。'''),
    (758, 'after', r'''onQueryProgress 每条消息都调——包括 runAgent  otherwise 丢弃的 stream_event delta。用于长单块流（如 thinking 连续 60s+ 不出 assistant 消息）时的活性检测。'''),
    (768, 'after', r'''TTFT 转发：subagent 的 API 请求开始事件推给父级指标显示，父级 UI 在 subagent 执行期间也能看到 TTFT/OTPS 更新。'''),
    (790, 'after', r'''max_turns_reached 是 query.ts 发来的 attachment 信号：记日志后 break 退出循环——正常收尾，不是错误。其他 attachment 原样 yield 不落盘。'''),
    (805, 'after', r'''可录制消息分支：逐条录 sidechain transcript（O(1)/条，挂 lastRecordedUuid），progress 消息不更新 UUID（它不是链上的正式节点）。'''),
    (810, 'after', r'''循环正常结束后补一次 abort 检查：query() 可能因为中断而自然结束，这时要抛 AbortError 让上层知道是被杀的。'''),
    (815, 'after', r'''内置 agent 的 callback 在 query 跑完后调用（如 statuslineSetup 装完状态栏）。'''),
    (859, 'after', r'''finally 清理链（正常结束/中断/出错都跑）：agent MCP 清理 → session 钩子 → prompt cache 追踪 → 克隆的文件缓存 → fork 消息引用 → perfetto 注册项 → transcript 子目录映射 → todos 键（whale 会话几百个 agent，每个不删的键都是泄漏）→ 后台 bash 任务（不杀会成 PPID=1 僵尸）→ MonitorMcpTask（feature 门控 + require 懒加载破循环依赖）。'''),
    (862, 'after', r'''filterIncompleteToolCalls：先扫出所有有结果的 tool_use_id，再滤掉包含未完成 tool_use 的 assistant 消息——API 不允许孤儿 tool_use，fork 上下文时必用。'''),
    (904, 'after', r'''过滤只针对 assistant 消息：非 assistant 消息和没有 tool_use 的 assistant 消息全留。'''),
    (932, 'after', r'''getAgentSystemPrompt：try 里调 agentDefinition.getSystemPrompt()，抛异常就回落 DEFAULT_AGENT_PROMPT——两条路都过 enhanceSystemPromptWithEnvDetails 补环境详情（模型名、工作目录、可用工具集）。'''),
    (934, 'after', r'''resolveSkillName：agent frontmatter 里写裸名，插件技能注册的是命名空间名（plugin:skill），三种策略逐级放宽。'''),
    (973, 'after', r'''后缀匹配是最后兜底：任意命令名以 :skillName 结尾就认——插件名前缀猜不出时（比如技能来自依赖插件而非 agent 所属插件）仍能解析。'''),
]
